import json
d=json.load(open('/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/277ff5fe-751b-42d1-9162-e255443f5b91/scratchpad/threads.json'))
ns=d['data']['repository']['pullRequest']['reviewThreads']['nodes']
print('total',len(ns),'unresolved',sum(1 for n in ns if not n['isResolved']))
for n in ns:
  if n['isResolved']: continue
  c=n['comments']['nodes'][0]
  print('---',n['id'],'outdated' if n['isOutdated'] else '','|',c['author']['login'],'|',c['path'],c['line'])
  print(c['body'][:1500])
  for extra in n['comments']['nodes'][1:]:
    print('  >>',extra['author']['login'],':',extra['body'][:500])
"

