import { renderToStaticMarkup } from "react-dom/server";
import { Tab, Tabs } from "@blueprintjs/core";

const render = (selected: string, enabled: boolean) =>
  renderToStaticMarkup(
    <Tabs id="s" selectedTabId={selected} vertical renderActiveTabPanelOnly>
      <Tab id="general" title="General" panel={<div>GENERAL_PANEL</div>} />
      <Tab
        id="left-sidebar"
        title="Left sidebar"
        hidden={!enabled}
        panel={<div>SIDEBAR_PANEL</div>}
      />
    </Tabs>,
  );

const sidebarTitle = (html: string) =>
  html.split("\n").find((l) => l.includes('data-tab-id="left-sidebar"')) ?? "";

const report = (label: string, selected: string, enabled: boolean) => {
  const html = render(selected, enabled).replace(/></g, ">\n<");
  console.log(
    label.padEnd(44),
    "tabHidden=" + String(/\shidden=""/.test(sidebarTitle(html))).padEnd(6),
    "panel=" +
      (html.includes("SIDEBAR_PANEL")
        ? "SIDEBAR"
        : html.includes("GENERAL_PANEL")
          ? "GENERAL"
          : "none"),
  );
};

report("enabled, on sidebar tab", "left-sidebar", true);
report("DISABLED, no guard (selection stranded)", "left-sidebar", false);
report("DISABLED, guard redirects", "general", false);
EOF
